import{_ as a,o as t,c as s,a3 as n}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"NestJS 核心","description":"AI Agent 服务所需的 NestJS 最小子集：启动、最小可 curl API、Module/DI、作用域、Controller/DTO 与 Guard/Interceptor/Filter。","frontmatter":{"title":"NestJS 核心","description":"AI Agent 服务所需的 NestJS 最小子集：启动、最小可 curl API、Module/DI、作用域、Controller/DTO 与 Guard/Interceptor/Filter。"},"headers":[],"relativePath":"ts-ai/backend/nestjs-core/index.md","filePath":"ts-ai/backend/nestjs-core/index.md","lastUpdated":1786113687000}'),r={name:"ts-ai/backend/nestjs-core/index.md"};function l(i,e,o,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="nestjs-核心" tabindex="-1">NestJS 核心 <a class="header-anchor" href="#nestjs-核心" aria-label="Permalink to &quot;NestJS 核心&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>NestJS 用 <strong>Module + 依赖注入</strong> 组织 Agent API。本分组是 <strong>AI 服务最小子集</strong>，不是 Nest 全书。</p><p><strong>会 Vue / TypeScript、几乎没写过后端？</strong> 把本分组当作后端入门课：按下方顺序 <strong>先跑通 curl，再拆 Module</strong>。完整裁剪主线见 <a href="/ts-ai/appendix/learning/frontend-backend-learning-path">前端出身学习路线</a>。</p><p><strong>建议读法：</strong></p><ol><li>扫一眼下方「一次 HTTP 请求怎么走」</li><li>打开<a href="/ts-ai/backend/nestjs-core/project-structure-bootstrap">项目结构与启动流程</a></li><li><strong>立刻</strong>跑通<a href="/ts-ai/backend/nestjs-core/minimal-agent-api-skeleton">最小可运行 Agent API</a>（假 Agent + <code>curl</code>）</li><li>按<a href="/ts-ai/backend/nestjs-core/skeleton-to-modules">从 Skeleton 拆到 Module</a> 拆边界（<strong>curl 契约不变</strong>）</li><li>再学 Module / 作用域 / Guard 百科与生产拼法（<a href="/ts-ai/backend/assembly/assembly-recipes-checklist">组装配方</a> §1）</li></ol><blockquote><p>不要按「先读完 Module 百科再写第一行代码」的顺序学——前端出身读者会在 DI 术语上劝退。先有可 curl 的结果，再理解容器为什么这样拆。</p></blockquote><h2 id="_1-一次-http-请求怎么走-人话" tabindex="-1">1. 一次 HTTP 请求怎么走（人话） <a class="header-anchor" href="#_1-一次-http-请求怎么走-人话" aria-label="Permalink to &quot;1. 一次 HTTP 请求怎么走（人话）&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求进入</span></span>
<span class="line"><span>  → CORS（浏览器跨域时）</span></span>
<span class="line"><span>  → Guard（有没有登录 / Token）</span></span>
<span class="line"><span>  → Interceptor 前半（打 traceId 等）</span></span>
<span class="line"><span>  → Pipe（校验 JSON 对不对）</span></span>
<span class="line"><span>  → Controller（收参）</span></span>
<span class="line"><span>  → Service（调 Agent）</span></span>
<span class="line"><span>  → Interceptor 后半 / 或 Filter（出错时统一错误 JSON）</span></span>
<span class="line"><span>  → 响应返回</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>后面各篇都是在讲其中一层怎么写。术语：Module ≈ 代码分区；Provider ≈ 可注入的服务类；DTO ≈ 请求体形状。</p><h2 id="_2-读者与边界" tabindex="-1">2. 读者与边界 <a class="header-anchor" href="#_2-读者与边界" aria-label="Permalink to &quot;2. 读者与边界&quot;">​</a></h2><ul><li>前置：会跑 TypeScript；了解 <a href="/ts-ai/agent/runtime/create-agent">createAgent</a> 概念即可，<strong>不要求</strong>已有 Nest 经验。rxjs Observable 细节到 <a href="/ts-ai/backend/api-realtime/sse-streaming">SSE</a> 再补即可。</li><li>不讲：微服务、ORM 深讲（→ <a href="/ts-ai/backend/data-tasks/">数据与任务</a>）、Gateway（→ <a href="/ts-ai/backend/ai-service/">AI 服务架构</a>）。</li><li>前端读者额外记住：<strong><code>OPENAI_API_KEY</code> 只存在于 Nest 进程</strong>；浏览器与 <code>NUXT_PUBLIC_*</code> 不得出现模型密钥。</li></ul><h2 id="_3-知识地图" tabindex="-1">3. 知识地图 <a class="header-anchor" href="#_3-知识地图" aria-label="Permalink to &quot;3. 知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>文章</th><th>核心问题</th></tr></thead><tbody><tr><td>1</td><td><a href="/ts-ai/backend/nestjs-core/project-structure-bootstrap">项目结构与启动流程</a></td><td><code>main.ts</code> 到监听端口</td></tr><tr><td>2</td><td><a href="/ts-ai/backend/nestjs-core/minimal-agent-api-skeleton">最小可运行 Agent API</a></td><td><strong>curl 出第一个 Run</strong></td></tr><tr><td>3</td><td><a href="/ts-ai/backend/nestjs-core/modules-providers-dependency-injection">Module、Provider 与依赖注入</a></td><td>服务怎么拆、怎么注入</td></tr><tr><td>4</td><td><a href="/ts-ai/backend/nestjs-core/scopes-lifecycle">作用域与生命周期</a></td><td>单例 vs 每请求一份</td></tr><tr><td>5</td><td><a href="/ts-ai/backend/nestjs-core/controllers-pipes-dto">Controller、Pipe 与 DTO</a></td><td>校验创建 Run 的 body</td></tr><tr><td>6</td><td><a href="/ts-ai/backend/nestjs-core/guards-interceptors-filters">Guard、Interceptor 与 Filter</a></td><td>鉴权、Trace、错误码</td></tr></tbody></table><h2 id="_4-下一步" tabindex="-1">4. 下一步 <a class="header-anchor" href="#_4-下一步" aria-label="Permalink to &quot;4. 下一步&quot;">​</a></h2><p>进入 <a href="/ts-ai/backend/ai-service/">AI 服务架构</a>。勾选见 <a href="/ts-ai/appendix/learning/knowledge-checklist">知识点清单</a> 中「NestJS 核心」一节。</p>`,16)])])}const h=a(r,[["render",l]]);export{b as __pageData,h as default};
